render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(from = cfg$x, to = cfg$y), c("from", "to")); from_values <- as.character(data[[cfg$x]]); to_values <- as.character(data[[cfg$y]]); nodes <- sort(unique(c(from_values, to_values))); ang <- seq(0, 2 * pi, length.out = length(nodes) + 1)[-(length(nodes) + 1)]; xy <- data.frame(node = nodes, x = cos(ang), y = sin(ang)); chart_open_device(cfg$outputPath, cfg$format); plot(xy$x, xy$y, type = "n", axes = FALSE, xlab = "", ylab = "", main = cfg$title %||% "边捆绑关系图"); for (i in seq_len(nrow(data))) { a <- xy[match(from_values[i], xy$node), ]; b <- xy[match(to_values[i], xy$node), ]; t <- seq(0, 1, length.out = 80); xx <- (1 - t)^2 * a$x + 2 * (1 - t) * t * 0 + t^2 * b$x; yy <- (1 - t)^2 * a$y + 2 * (1 - t) * t * 0 + t^2 * b$y; lines(xx, yy, col = cfg$color %||% "#0A84FF", lwd = 1.5, alpha = 0.65); }; points(xy$x, xy$y, pch = 21, bg = "white", col = cfg$color %||% "#0A84FF", cex = 2); text(xy$x, xy$y, xy$node, pos = 3, cex = 0.9); box(); grDevices::dev.off(); cfg$outputPath }
